CREATE    PROCEDURE [synapse_ce].[usp_Insert_connection]
AS
BEGIN

;WITH cte AS
	(
		SELECT 
		[connectionid],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[effectiveend],
		[effectivestart],
		[entityimage_timestamp],
		[entityimage_url],
		[entityimageid],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[ismaster],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[name],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[record1id],
		[record1id_entitytype],
		[record1idname],
		[record1idobjecttypecode],
		[record1objecttypecode],
		[record1roleid],
		[record1roleid_entitytype],
		[record1roleidname],
		[record2id],
		[record2id_entitytype],
		[record2idname],
		[record2idobjecttypecode],
		[record2objecttypecode],
		[record2roleid],
		[record2roleid_entitytype],
		[record2roleidname],
		[relatedconnectionid],
		[relatedconnectionid_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[versionnumber],
		ROW_NUMBER() OVER(PARTITION BY ID ORDER BY ID DESC) AS RowNo
		FROM [staging_ce].[connection] 
	)


	INSERT INTO [synapse_ce].[connection]
	(
		[connectionid],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[effectiveend],
		[effectivestart],
		[entityimage_timestamp],
		[entityimage_url],
		[entityimageid],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[ismaster],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[name],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[record1id],
		[record1id_entitytype],
		[record1idname],
		[record1idobjecttypecode],
		[record1objecttypecode],
		[record1roleid],
		[record1roleid_entitytype],
		[record1roleidname],
		[record2id],
		[record2id_entitytype],
		[record2idname],
		[record2idobjecttypecode],
		[record2objecttypecode],
		[record2roleid],
		[record2roleid_entitytype],
		[record2roleidname],
		[relatedconnectionid],
		[relatedconnectionid_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[versionnumber]
	)
	SELECT 
		stg.[connectionid],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[effectiveend],
		stg.[effectivestart],
		stg.[entityimage_timestamp],
		stg.[entityimage_url],
		stg.[entityimageid],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[ismaster],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[name],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[record1id],
		stg.[record1id_entitytype],
		stg.[record1idname],
		stg.[record1idobjecttypecode],
		stg.[record1objecttypecode],
		stg.[record1roleid],
		stg.[record1roleid_entitytype],
		stg.[record1roleidname],
		stg.[record2id],
		stg.[record2id_entitytype],
		stg.[record2idname],
		stg.[record2idobjecttypecode],
		stg.[record2objecttypecode],
		stg.[record2roleid],
		stg.[record2roleid_entitytype],
		stg.[record2roleidname],
		stg.[relatedconnectionid],
		stg.[relatedconnectionid_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[versionnumber]	
	FROM cte stg --[staging_ce].[connection] stg
		LEFT JOIN [synapse_ce].[connection] tgt
			ON tgt.[id] = stg.[id]
	WHERE RowNo = 1 
	AND tgt.[id] IS NULL
END
